package com.aetherforge.api;
import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;
@RestControllerAdvice public class ApiErrorHandler { @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<?> badRequest(IllegalArgumentException e,HttpServletRequest r){return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now(),"status",400,"error","Bad Request","message",e.getMessage()==null?"Invalid request":e.getMessage(),"path",r.getRequestURI(),"requestId",UUID.randomUUID().toString()));} @ExceptionHandler(SecurityException.class) ResponseEntity<?> forbidden(SecurityException e,HttpServletRequest r){return ResponseEntity.status(403).body(Map.of("timestamp",Instant.now(),"status",403,"error","Forbidden","message","You are not authorized for this action.","path",r.getRequestURI(),"requestId",UUID.randomUUID().toString()));} @ExceptionHandler(IllegalStateException.class) ResponseEntity<?> conflict(IllegalStateException e,HttpServletRequest r){return ResponseEntity.status(409).body(Map.of("timestamp",Instant.now(),"status",409,"error","Conflict","message",e.getMessage()==null?"Invalid state":e.getMessage(),"path",r.getRequestURI(),"requestId",UUID.randomUUID().toString()));} @ExceptionHandler(Exception.class) ResponseEntity<?> generic(Exception e,HttpServletRequest r){return ResponseEntity.status(500).body(Map.of("timestamp",Instant.now(),"status",500,"error","Internal Server Error","message","The service could not complete this request.","path",r.getRequestURI(),"requestId",UUID.randomUUID().toString()));} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> validation(MethodArgumentNotValidException e,HttpServletRequest r){var m=e.getBindingResult().getFieldErrors().stream().collect(java.util.stream.Collectors.toMap(x->x.getField(),x->x.getDefaultMessage()==null?"Invalid value":x.getDefaultMessage(),(a,b)->a));return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now(),"status",400,"error","Validation Error","message","Request validation failed","path",r.getRequestURI(),"requestId",UUID.randomUUID().toString(),"validationErrors",m));} }
